import { Request, Response } from 'express';
import { AssignTaskUseCase } from '../../../application/use-cases/AssignTaskUseCase';
import { CompleteTaskUseCase } from '../../../application/use-cases/CompleteTaskUseCase';
import { CreateTaskUseCase } from '../../../application/use-cases/CreateTaskUseCase';
import { ListProjectTasksUseCase } from '../../../application/use-cases/ListProjectTasksUseCase';
import { RequestReader } from '../RequestReader';

export interface TaskUseCases {
  createTask: CreateTaskUseCase;
  listProjectTasks: ListProjectTasksUseCase;
  assignTask: AssignTaskUseCase;
  completeTask: CompleteTaskUseCase;
}

export class TaskController {
  constructor(private readonly useCases: TaskUseCases) {}

  create = async (req: Request<{ projectId: string }>, res: Response): Promise<void> => {
    const body = new RequestReader(req.body);
    const task = await this.useCases.createTask.execute({
      projectId: req.params.projectId,
      title: body.requiredString('title'),
      description: body.requiredString('description'),
      dueDate: body.optionalString('dueDate'),
      status: body.optionalString('status'),
      assigneeId: body.optionalString('assigneeId'),
    });
    res.status(201).json(task);
  };

  listByProject = async (req: Request<{ projectId: string }>, res: Response): Promise<void> => {
    const query = new RequestReader(req.query);
    const tasks = await this.useCases.listProjectTasks.execute({
      projectId: req.params.projectId,
      status: query.optionalString('status'),
      assigneeId: query.optionalString('assigneeId'),
    });
    res.json(tasks);
  };

  assign = async (req: Request<{ taskId: string }>, res: Response): Promise<void> => {
    const body = new RequestReader(req.body);
    const task = await this.useCases.assignTask.execute({
      taskId: req.params.taskId,
      userId: body.requiredString('userId'),
    });
    res.json(task);
  };

  complete = async (req: Request<{ taskId: string }>, res: Response): Promise<void> => {
    const task = await this.useCases.completeTask.execute(req.params.taskId);
    res.json(task);
  };
}

=====SOURCE-END=====

